"use strict";
const fs=require('node:fs'),path=require('node:path'),os=require('node:os'),{spawn}=require('node:child_process');
const plugin=path.resolve(__dirname,'../..'),candidate=path.resolve(process.argv[2]??plugin);
const scratch=fs.mkdtempSync(path.join(os.tmpdir(),'hub-capture-runtime-')),vault=path.join(scratch,'vault'),profile=path.join(scratch,'profile'),target=path.join(vault,'.obsidian/plugins/hub-project-menu');
fs.mkdirSync(target,{recursive:true});fs.mkdirSync(profile,{recursive:true});
fs.copyFileSync(path.join(candidate,'main.js'),path.join(target,'main.js'));fs.copyFileSync(path.join(plugin,'styles.css'),path.join(target,'styles.css'));fs.copyFileSync(path.join(plugin,'manifest.json'),path.join(target,'manifest.json'));
fs.appendFileSync(path.join(target,'main.js'),`\nmodule.exports = class CaptureFixturePlugin extends require('obsidian').Plugin { onload() { this.captureTest = {api: require('obsidian'),service:__hubRequire('lib/services/inbox.js'),store:__hubRequire('lib/services/data-store.js'),quick:__hubRequire('lib/ui/quick-add.js'),controls:__hubRequire('lib/ui/capture-controls.js'),inbox:__hubRequire('lib/ui/inbox.js'),task:__hubRequire('lib/ui/task-editor.js'),locations:__hubRequire('lib/services/native-task-locations.js')}; } };\n`);
for(const folder of ['Projects','Projects/Fixture','Projects/Fixture/Nested','Resources','Resources/Explorations'])fs.mkdirSync(path.join(vault,folder),{recursive:true});
fs.writeFileSync(path.join(vault,'Projects/Fixture/Fixture.md'),'# Fixture\n');
fs.writeFileSync(path.join(vault,'Home.md'),'# Capture fixture\n');fs.writeFileSync(path.join(vault,'Projects/Fixture/Nested/Note.md'),'Existing\r\n');fs.writeFileSync(path.join(vault,'Resources/Explorations/Explorations.md'),'# Explorations\n');
fs.writeFileSync(path.join(vault,'.obsidian/community-plugins.json'),JSON.stringify(['hub-project-menu']));fs.writeFileSync(path.join(vault,'.obsidian/app.json'),JSON.stringify({safeMode:false,showInlineTitle:true}));fs.writeFileSync(path.join(vault,'.obsidian/appearance.json'),JSON.stringify({theme:'obsidian',cssTheme:'',baseFontSize:17,nativeMenus:false}));fs.writeFileSync(path.join(profile,'obsidian.json'),JSON.stringify({vaults:{capturefixture:{path:vault,ts:1,open:true}},cli:false,updateDisabled:true}));
const archive=process.env.HUB_CAPTURE_OBSIDIAN_ARCHIVE??path.join(process.env.APPDATA,'obsidian',fs.readdirSync(path.join(process.env.APPDATA,'obsidian')).filter(n=>/^obsidian-[0-9.]+\.asar$/.test(n)).sort((a,b)=>b.localeCompare(a,undefined,{numeric:true}))[0]);
const binary=path.join(plugin,'lib/atlas/tests/native/node_modules/electron/dist/electron.exe');
async function run(phase){return new Promise((resolve,reject)=>{const env={...process.env,HUB_CAPTURE_RUNTIME_ROOT:scratch,HUB_CAPTURE_OBSIDIAN_ARCHIVE:archive,HUB_CAPTURE_PHASE:phase};delete env.ELECTRON_RUN_AS_NODE;let passed=false;const child=spawn(binary,[path.join(__dirname,'capture-obsidian-host.cjs')],{env,windowsHide:true,stdio:['ignore','pipe','pipe']});child.stdout.on('data',b=>{process.stdout.write(b);passed||=b.toString().includes('PASS genuine capture phase '+phase);});child.stderr.on('data',b=>process.stderr.write(b));child.on('error',reject);child.on('close',code=>code===0&&passed?resolve():reject(Error('Capture phase '+phase+' failed: '+code)));});}
(async()=>{try{await run('first');await run('restart');await run('files');console.log('PASS genuine capture restart and UI workflows');}catch(error){console.error(error.stack);process.exitCode=1;}finally{console.log('Capture evidence:',scratch);}})();
